const {seeds,fresh,value,suitable,settle,validate}=SP,KEY='season-planet-v1';
let s=fresh(),selected=-1,anchor=0,locked=false,storageOK=true;const $=id=>document.getElementById(id);
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').style.display='none',4000);}
try{const raw=localStorage.getItem(KEY);if(raw){try{s=JSON.parse(raw);if(!validate(s))throw Error();}catch{const b=JSON.parse(localStorage.getItem(KEY+'-backup'));if(!validate(b))throw Error('存档损坏，请先保留浏览器数据再联系开发者');s=b;toast('已恢复上一份有效存档');}if(s.phase==='running')s.phase='paused';}}catch(e){storageOK=false;toast(e.message||'无法读取本地存档');}
function commit(n){if(locked||!storageOK){toast('当前存档不可写入，请刷新或关闭其他窗口');return false;}try{const raw=localStorage.getItem(KEY),old=raw?JSON.parse(raw):null;if(old&&old.rev!==s.rev){locked=true;throw Error('其他窗口已更新存档，请关闭其他窗口并刷新');}n.rev=s.rev+1;const data=JSON.stringify(n);if(raw&&validate(old))localStorage.setItem(KEY+'-backup',raw);localStorage.setItem(KEY,data);s=n;return true;}catch(e){toast('保存失败：'+e.message);return false;}}
function mutate(fn){const n=JSON.parse(JSON.stringify(s));fn(n);if(commit(n))render();}
function elapsed(){return Math.min(s.duration,s.elapsed+(s.phase==='running'?performance.now()-anchor:0));}
function checkpoint(pause=false){const n={...s,elapsed:elapsed(),phase:pause?'paused':s.phase};if(commit(n)){anchor=performance.now();render();}else{s.phase='paused';render();}}
function render(){const editable=s.phase==='ready'&&!locked&&storageOK;$('wallet').textContent='✦ '+s.coins+' 金币';$('season').textContent=['春 · 萌芽','夏 · 繁盛','秋 · 丰收','冬 · 静候'][s.season];$('value').textContent=value(s)+' 金币';$('status').textContent=locked?'其他窗口已更新，请刷新':s.phase==='running'?'专注中 · 星球正在等待这一季的收获':s.phase==='paused'?'本季已暂停，随时可以继续':'准备好了，就开始这一季吧';$('start').textContent=s.phase==='running'?'暂停':s.phase==='paused'?'继续专注':'开始专注';$('start').disabled=locked||!storageOK;$('cancel').disabled=s.phase==='ready';$('demo').checked=s.duration===10000;$('demo').disabled=!editable;$('selection').textContent=selected<0?'先选择一块土地':'已选择土地 '+(selected+1);$('plots').replaceChildren();s.plots.forEach((i,k)=>{const b=document.createElement('button');b.className='plot'+(selected===k?' active':'');const icon=document.createElement('span');icon.className='sprout';icon.textContent=i===null?'+':seeds[i].icon;b.append(icon,document.createTextNode(i===null?'空地 · 点击选择':seeds[i].name+(suitable(s,i)?'':' · 休眠')));b.onclick=()=>{selected=k;render();};$('plots').append(b);});$('metrics').innerHTML=s.env.map((v,k)=>'<div class="metric">'+['氧气','含水量','温度','丰饶度'][k]+'<span>'+v+'</span><div class="meter"><i style="width:'+v+'%"></i></div></div>').join('');$('shop').replaceChildren();seeds.forEach((seed,i)=>{const row=document.createElement('div');row.className='seed';const info=document.createElement('div');const title=document.createElement('b');title.textContent=seed.icon+' '+seed.name+' · '+seed.price+' 金币';const p=document.createElement('p');p.textContent=(i<4?['氧气 +8','水分 +8','温度 −6','丰饶 +8'][i]:i===4?'耐受型作物':'需氧气40–75 / 水40–75 / 温30–65 / 丰饶35–85')+' · 每季 '+seed.yield+' 个 / 单价 '+seed.sell+' · 种子库存 '+s.seeds[i];info.append(title,p);const buttons=document.createElement('div'),buy=document.createElement('button'),plant=document.createElement('button');buy.textContent='购买';buy.disabled=!editable||s.coins<seed.price;buy.onclick=()=>mutate(n=>{n.coins-=seed.price;n.seeds[i]++;});plant.textContent='种植';plant.disabled=!editable||selected<0||s.plots[selected]!==null||s.seeds[i]<1;plant.onclick=()=>mutate(n=>{n.seeds[i]--;n.plots[selected]=i;});buttons.append(buy,plant);row.append(info,buttons);$('shop').append(row);});if(selected>=0&&s.plots[selected]!==null){const b=document.createElement('button');b.textContent='移除所选植物（不退款）';b.disabled=!editable;b.onclick=()=>{if(confirm('移除此植物？不会退回种子。'))mutate(n=>n.plots[selected]=null);};$('shop').append(b);}$('inventory').textContent=s.crops.map((v,i)=>v?seeds[i].name+'果 ×'+v:'').filter(Boolean).join(' · ')||'还没有收获，先种下一颗种子吧。';$('sellCrops').disabled=!editable||!s.crops.some(Boolean);$('sellPlanet').disabled=!editable||s.round<1||value(s)<=0;$('log').textContent=s.log;tickClock();}
function tickClock(){const sec=Math.ceil((s.duration-elapsed())/1000);$('clock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
$('start').onclick=()=>{if(s.phase==='running'){checkpoint(true);return;}const n={...s,phase:'running'};if(commit(n)){anchor=performance.now();render();}};
$('cancel').onclick=()=>{if(confirm('放弃本次计时？植物保留，本季时间归零。'))mutate(n=>{n.elapsed=0;n.phase='ready';});};
$('demo').onchange=()=>mutate(n=>{n.duration=$('demo').checked?10000:1800000;n.elapsed=0;});
$('sellCrops').onclick=()=>mutate(n=>{const income=n.crops.reduce((a,v,i)=>a+v*seeds[i].sell,0);n.coins+=income;n.crops.fill(0);n.log='售出作物，获得 '+income+' 金币。';});
$('sellPlanet').onclick=()=>{const price=value(s);if(confirm('以 '+price+' 金币出售星球及地上植物？金币、作物和未使用种子保留。'))mutate(n=>{const base=fresh();n.coins+=price;n.env=base.env;n.plots=base.plots;n.round=0;n.season=0;n.elapsed=0;n.log='星球交接完成，获得 '+price+' 金币。一颗新星球正等待你。';});};
$('reset').onclick=()=>{if(confirm('清空本机全部游戏进度？')){if(commit({...fresh(),rev:s.rev})){selected=-1;render();}}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&s.phase==='running')checkpoint(true);});window.addEventListener('pagehide',()=>{if(s.phase==='running')checkpoint(true);});window.addEventListener('storage',e=>{if(e.key===KEY){locked=true;if(s.phase==='running'){s.elapsed=elapsed();s.phase='paused';}render();toast('其他窗口已更新进度，请刷新本页后继续');}});
setInterval(()=>{if(s.phase!=='running')return;if(elapsed()>=s.duration){const n=settle({...s,elapsed:s.duration});if(commit(n)){render();toast('一个季节完成了，来看看星球的变化吧');}else{s.phase='paused';render();}}else tickClock();},200);setInterval(()=>{if(s.phase==='running')checkpoint();},5000);render();
